import{_ as i,o as a,c as t,a3 as l,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/reportdesigner/tutorials-dokumentenablage-ordner-aendern.png",s="/bilder/reportdesigner/tutorials-dokumentenablage-ordner-aendern-gruppenprozess.png",k=JSON.parse('{"title":"Das Verzeichnis der Dokumentenablage ändern","description":"","frontmatter":{"title":"Das Verzeichnis der Dokumentenablage ändern","source_pageid":1338,"source_revision":6690},"headers":[],"relativePath":"reporting/reportdesigner/verzeichnis-der-dokumentenverwaltung-aendern-tutorial.md","filePath":"reporting/reportdesigner/verzeichnis-der-dokumentenverwaltung-aendern-tutorial.md"}'),o={name:"reporting/reportdesigner/verzeichnis-der-dokumentenverwaltung-aendern-tutorial.md"};function u(g,n,h,c,p,m){return a(),t("div",null,[...n[0]||(n[0]=[l('<h1 id="das-verzeichnis-der-dokumentenablage-andern" tabindex="-1">Das Verzeichnis der Dokumentenablage ändern <a class="header-anchor" href="#das-verzeichnis-der-dokumentenablage-andern" aria-label="Permalink to &quot;Das Verzeichnis der Dokumentenablage ändern&quot;">​</a></h1><p>Ändern Sie den Ablageort und bei Bedarf die Dateimaske der Dokumentenverwaltung. Entscheiden Sie dabei, ob die neue Ablage nur für neu aufgenommene oder auch für bereits vorhandene Schülerinnen und Schüler gelten soll.</p><h2 id="_1-den-neuen-ablageort-einstellen" tabindex="-1">1. Den neuen Ablageort einstellen <a class="header-anchor" href="#_1-den-neuen-ablageort-einstellen" aria-label="Permalink to &quot;1. Den neuen Ablageort einstellen&quot;">​</a></h2><p><a href="/bilder/reportdesigner/tutorials-dokumentenablage-ordner-aendern.png"><img src="'+d+'" alt="Über Verwaltung Einstellungen Dokumentenverwaltung lassen sich Ordner und Maske der Dokumentenverwaltung einstellen und ändern." loading="lazy"></a></p><p><em>Über Verwaltung Einstellungen Dokumentenverwaltung lassen sich Ordner und Maske der Dokumentenverwaltung einstellen und ändern.</em></p><p>Öffnen Sie <strong>Verwaltung → Einstellungen → Dokumentenverwaltung</strong> und ändern Sie <strong>Dokumentenverzeichnis</strong>. Bei Bedarf können Sie dort auch die <strong>Dateimaske</strong> neu festlegen.</p><p>Ein Klick auf <strong>Dokumentenverzeichnisse für alle Schüler anlegen</strong> ändert die bereits gespeicherten Verzeichnisse vorhandener Schülerinnen und Schüler nicht. Deren individuelle Ablagepfade bleiben in der Datenbank erhalten.</p><p>Wenn die neue Ablage nur für künftig angelegte Schülerinnen und Schüler gelten soll, können Sie mit dieser Einstellung weiterarbeiten. Für vorhandene Personen werden dann weiterhin das bisherige Verzeichnis und die bisherige Maske verwendet.</p><h2 id="_2-vorhandene-ablagen-umstellen" tabindex="-1">2. Vorhandene Ablagen umstellen <a class="header-anchor" href="#_2-vorhandene-ablagen-umstellen" aria-label="Permalink to &quot;2. Vorhandene Ablagen umstellen&quot;">​</a></h2><p>Die folgenden Schritte sind nur erforderlich, wenn auch bestehende Schülerablagen den neuen Ort verwenden sollen.</p><h3 id="die-gespeicherten-schulerpfade-andern" tabindex="-1">Die gespeicherten Schülerpfade ändern <a class="header-anchor" href="#die-gespeicherten-schulerpfade-andern" aria-label="Permalink to &quot;Die gespeicherten Schülerpfade ändern&quot;">​</a></h3><p><a href="/bilder/reportdesigner/tutorials-dokumentenablage-ordner-aendern-gruppenprozess.png"><img src="'+s+'" alt="Starten Sie den Gruppenprozess für die ganze Schule." loading="lazy"></a></p><p><em>Starten Sie den Gruppenprozess für die ganze Schule.</em></p><ol><li>Wählen Sie im Schülercontainer die betroffene Gruppe aus. Für eine vollständige Umstellung ist dies üblicherweise die ganze Schule.</li><li>Rufen Sie <strong>Gruppenprozesse → Allgemein → Dokumentenverzeichnisse</strong> auf.</li><li>Passen Sie damit die individuellen Einträge an das neue Verzeichnis und die neue Maske an.</li></ol><h3 id="die-vorhandenen-dateien-ubertragen" tabindex="-1">Die vorhandenen Dateien übertragen <a class="header-anchor" href="#die-vorhandenen-dateien-ubertragen" aria-label="Permalink to &quot;Die vorhandenen Dateien übertragen&quot;">​</a></h3><p>Markieren Sie im Windows-Explorer die zu übertragenden Schüler-Unterordner und fügen Sie sie im neuen Zielordner ein:</p><ul><li><strong>Kopieren und Einfügen</strong> lässt die bisherige Ablage bestehen.</li><li><strong>Ausschneiden und Einfügen</strong> entfernt die übertragenen Dateien am alten Ort. Ein anschließend leerer alter Ordner kann gelöscht werden.</li></ul>',17),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),r("Wichtig – Geänderte Dateimaske berücksichtigen")]),e("p",null,"Wenn sich der individuelle Schülerpfad durch die neue Dateimaske ändert, lassen sich die Dateien nicht allein durch Kopieren des alten Gesamtordners an den neuen Ort zuordnen. Berücksichtigen Sie dann auch die geänderte Unterordnerstruktur.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Verzeichnis_der_Dokumentenverwaltung_%C3%A4ndern_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),r(" · Quellrevision 6690.")],-1)])])}const f=i(o,[["render",u]]);export{k as __pageData,f as default};
